CREATE TABLE account_coa (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, HeadCode BIGINT UNSIGNED NOT NULL, HeadName VARCHAR(100) NOT NULL, PHeadName VARCHAR(100) NULL, parent_id BIGINT UNSIGNED NULL, HeadLevel INT NOT NULL DEFAULT 0, IsActive BOOLEAN NOT NULL DEFAULT TRUE, IsTransaction BOOLEAN NOT NULL DEFAULT FALSE, IsGL BOOLEAN NOT NULL DEFAULT FALSE, IsJournal BOOLEAN NOT NULL DEFAULT FALSE, HeadType CHAR(1) NULL, IsBudget BOOLEAN NOT NULL DEFAULT FALSE, IsDepreciation BOOLEAN NOT NULL DEFAULT FALSE, customer_id BIGINT UNSIGNED NULL, aggre_id BIGINT UNSIGNED NULL, supplier_id BIGINT UNSIGNED NULL, employee_id BIGINT UNSIGNED NULL, payment_method_id VARCHAR(255) NULL, bank_id VARCHAR(255) NULL, node_type ENUM('root','group','control','ledger') NOT NULL DEFAULT 'group', allows_manual_children BOOLEAN NOT NULL DEFAULT FALSE, is_system BOOLEAN NOT NULL DEFAULT FALSE, CreateBy VARCHAR(50) NULL, CreateDate DATE NULL, UpdateBy VARCHAR(50) NULL, UpdateDate DATE NULL, deleted_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY account_coa_head_code_unique(HeadCode), KEY account_coa_parent_index(parent_id), CONSTRAINT account_coa_parent_fk FOREIGN KEY(parent_id) REFERENCES account_coa(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

