CREATE TEMPORARY TABLE account_coa_parent_map AS SELECT id,HeadName FROM account_coa;
UPDATE account_coa child JOIN account_coa_parent_map parent ON parent.HeadName=child.PHeadName SET child.parent_id=parent.id WHERE child.PHeadName IS NOT NULL;
